(()=>{document.addEventListener('DOMContentLoaded',()=>{const steps=document.querySelectorAll('.step');const formSteps=document.querySelectorAll('.form-step');const progressBar=document.getElementById('progress-bar');const progressContainer=document.querySelector('.progress-container');const nextButtons=document.querySelectorAll('[data-next-step]');const prevButtons=document.querySelectorAll('[data-prev-step]');const registerBtn=document.getElementById('register-btn');const verifyBtn=document.getElementById('verify-btn');let currentStep=1;const totalSteps=3;const updateProgress=()=>{if(progressBar){const progress=totalSteps>1?((currentStep-1)/(totalSteps-1))*100:0;progressBar.style.width=`${progress}%`;}
steps.forEach((step)=>{const stepNumber=Number(step.getAttribute('data-step'));step.classList.remove('active','completed');if(stepNumber<currentStep){step.classList.add('completed');}else if(stepNumber===currentStep){step.classList.add('active');}});};const showCurrentStep=()=>{formSteps.forEach((step)=>{step.classList.remove('active');});const activeStep=document.getElementById(`step-${currentStep}`);if(activeStep){activeStep.classList.add('active');}};const goToStep=(stepNumber)=>{currentStep=Math.max(1,Math.min(stepNumber,totalSteps));showCurrentStep();updateProgress();if(progressContainer){progressContainer.style.display='';}};nextButtons.forEach((button)=>{button.addEventListener('click',()=>{if(currentStep<totalSteps){currentStep+=1;goToStep(currentStep);}});});prevButtons.forEach((button)=>{button.addEventListener('click',()=>{if(currentStep>1){currentStep-=1;goToStep(currentStep);}});});if(registerBtn){registerBtn.addEventListener('click',()=>{const terms=document.getElementById('terms');if(terms&&!terms.checked){window.alert('Debes aceptar los términos y condiciones para continuar.');return;}
const step3=document.getElementById('step-3');const step4=document.getElementById('step-4');if(step3){step3.classList.remove('active');}
if(step4){step4.classList.add('active');}
if(progressContainer){progressContainer.style.display='none';}
const emailSent=document.getElementById('email-sent');const emailField=document.getElementById('email');if(emailSent&&emailField){emailSent.textContent=emailField.value||emailSent.textContent;}});}
if(verifyBtn){verifyBtn.addEventListener('click',()=>{const codeField=document.getElementById('verification_code');if(codeField&&!codeField.value){window.alert('Por favor, introduce el código de verificación.');return;}
window.alert('¡Cuenta verificada con éxito! Ahora puedes iniciar sesión.');});}
const channelButtons=document.querySelectorAll('.channel-btn');const companySection=document.getElementById('company-section');if(companySection){companySection.setAttribute('aria-hidden','true');}
const updateChannel=(channel)=>{channelButtons.forEach((button)=>{button.classList.toggle('active',button.getAttribute('data-channel')===channel);});if(companySection){const showCompanyFields=channel==='professional';companySection.hidden=!showCompanyFields;companySection.setAttribute('aria-hidden',showCompanyFields?'false':'true');}};if(channelButtons.length){channelButtons.forEach((button)=>{button.addEventListener('click',()=>{const channel=button.getAttribute('data-channel');updateChannel(channel);});});}
const toggleVisibility=(checkboxId,fieldId)=>{const checkbox=document.getElementById(checkboxId);const field=document.getElementById(fieldId);if(!checkbox||!field){return;}
const update=()=>{field.classList.toggle('visible',checkbox.checked);};checkbox.addEventListener('change',update);update();};toggleVisibility('has_workshop','workshop-fields');toggleVisibility('has_web','web-field');toggleVisibility('auto_signature','signature-fields');toggleVisibility('enable_sepa','sepa-fields');const avatarUpload=document.getElementById('avatar-upload');const avatarInput=document.getElementById('avatar');const avatarPreview=document.getElementById('avatar-preview');const avatarPreviewImage=avatarPreview?avatarPreview.querySelector('img'):null;const resetAvatarPreview=()=>{if(avatarPreview){avatarPreview.hidden=true;avatarPreview.setAttribute('aria-hidden','true');}
if(avatarPreviewImage){avatarPreviewImage.removeAttribute('src');}};if(avatarUpload&&avatarInput){avatarUpload.addEventListener('click',()=>{avatarInput.click();});avatarInput.addEventListener('change',()=>{const label=avatarUpload.querySelector('.file-label');if(label){label.textContent=avatarInput.files&&avatarInput.files.length?'Imagen seleccionada':'+ Añadir imagen de perfil';}
if(!avatarPreview||!avatarPreviewImage){return;}
if(avatarInput.files&&avatarInput.files.length){const[file]=avatarInput.files;if(file&&file.type&&file.type.startsWith('image/')){const reader=new FileReader();reader.addEventListener('load',()=>{if(typeof reader.result==='string'){avatarPreviewImage.src=reader.result;avatarPreview.hidden=false;avatarPreview.setAttribute('aria-hidden','false');}});reader.readAsDataURL(file);}else{resetAvatarPreview();}}else{resetAvatarPreview();}});}
document.querySelectorAll('.password-toggle').forEach((toggle)=>{const targetId=toggle.getAttribute('data-target');const input=targetId?document.getElementById(targetId):null;if(!input){return;}
toggle.addEventListener('click',()=>{const revealPassword=input.type==='password';input.type=revealPassword?'text':'password';toggle.classList.toggle('is-active',revealPassword);toggle.setAttribute('aria-label',revealPassword?'Ocultar contraseña':'Mostrar contraseña');});});document.querySelectorAll('.help-trigger').forEach((trigger)=>{const targetId=trigger.getAttribute('data-help-target');const panel=targetId?document.getElementById(targetId):null;if(!panel){return;}
const closeBtn=panel.querySelector('[data-help-dismiss]');const setExpanded=(expanded)=>{trigger.classList.toggle('is-active',expanded);trigger.setAttribute('aria-expanded',expanded?'true':'false');panel.hidden=!expanded;panel.classList.toggle('is-active',expanded);};trigger.addEventListener('click',()=>{const willExpand=!trigger.classList.contains('is-active');setExpanded(willExpand);});if(closeBtn){closeBtn.addEventListener('click',()=>{setExpanded(false);});}
setExpanded(false);});showCurrentStep();updateProgress();});})();